struct Codec;impl Codec{fn new()->Self{Self}fn encode(&self,s:Vec<String>)->String{let mut r=String::new();for x in s{r.push_str(&format!("{}#{}",x.len(),x));}r}fn decode(&self,s:String)->Vec<String>{let b=s.as_bytes();let mut i=0;let mut o=vec![];while i<b.len(){let mut j=i;while b[j]!=b'#'{j+=1}let n=s[i..j].parse::<usize>().unwrap();o.push(s[j+1..j+1+n].to_string());i=j+1+n;}o}}
